import sys
import xml.etree.ElementTree as ET
import json
from datetime import datetime, timezone
import os

def parse_config():
    try:
        tree = ET.parse('access.xml')
        root = tree.getroot()
    except FileNotFoundError:
        print("ERROR: configuration", file=sys.stderr)
        sys.exit(2)
    except ET.ParseError:
        print("ERROR: configuration", file=sys.stderr)
        sys.exit(2)

    if root.tag != 'access':
        print("ERROR: configuration", file=sys.stderr)
        sys.exit(2)

    roles = {}
    users = {}

    roles_elem = root.find('roles')
    if roles_elem is None:
        print("ERROR: configuration", file=sys.stderr)
        sys.exit(2)

    for role_elem in roles_elem.findall('role'):
        role_name = role_elem.get('name')
        if role_name is None:
            print("ERROR: configuration", file=sys.stderr)
            sys.exit(2)
        allowed_resources = set()
        for allow_elem in role_elem.findall('allow'):
            resource = allow_elem.get('resource')
            if resource is None:
                print("ERROR: configuration", file=sys.stderr)
                sys.exit(2)
            allowed_resources.add(resource)
        roles[role_name] = allowed_resources

    users_elem = root.find('users')
    if users_elem is None:
        print("ERROR: configuration", file=sys.stderr)
        sys.exit(2)

    for user_elem in users_elem.findall('user'):
        user_name = user_elem.get('name')
        if user_name is None:
            print("ERROR: configuration", file=sys.stderr)
            sys.exit(2)
        token = user_elem.get('token')
        role = user_elem.get('role')
        if token is None or role is None:
            print("ERROR: configuration", file=sys.stderr)
            sys.exit(2)
        users[token] = {'user': user_name, 'role': role}

    return roles, users

def check_access(token, resource, roles, users):
    user_info = users.get(token)
    if user_info is None:
        return 'DENY', 'null'

    user = user_info['user']
    role = user_info['role']
    allowed = roles.get(role, set())

    if resource in allowed:
        return 'ALLOW', user
    else:
        return 'DENY', user

def main():
    roles, users = parse_config()

    log_file = 'access.log'
    with open(log_file, 'a') as log:
        for line in sys.stdin:
            parts = line.strip().split()
            if len(parts) != 2:
                continue
            token, resource = parts
            decision, user = check_access(token, resource, roles, users)
            print(decision)
            timestamp = datetime.now(timezone.utc).isoformat() + 'Z'
            log_entry = {
                'timestamp': timestamp,
                'user': user,
                'resource': resource,
                'decision': decision
            }
            log.write(json.dumps(log_entry) + '\n')

if __name__ == '__main__':
    main()

import sys
import json
import xml.etree.ElementTree as ET
from datetime import datetime, timezone
from typing import Dict, List, Optional

def parse_access_xml(file_path: str) -> Dict[str, Dict[str, List[str]]]:
    try:
        tree = ET.parse(file_path)
        root = tree.getroot()
    except (ET.ParseError, FileNotFoundError):
        sys.stderr.write("ERROR: configuration\n")
        sys.exit(2)

    users = {}
    roles = {}

    for user_elem in root.findall('user'):
        name = user_elem.get('name')
        token = user_elem.get('token')
        role = user_elem.get('role')
        if name and token and role:
            users[token] = {'name': name, 'role': role}

    for role_elem in root.findall('role'):
        role_name = role_elem.get('name')
        resource = role_elem.get('resource')
        if role_name and resource:
            if role_name not in roles:
                roles[role_name] = []
            roles[role_name].append(resource)

    return {'users': users, 'roles': roles}

def process_input(users: Dict[str, Dict[str, str]], roles: Dict[str, List[str]]) -> None:
    for line in sys.stdin:
        parts = line.strip().split()
        if len(parts) != 2:
            continue
        token, resource = parts
        user_info = users.get(token, None)
        user_name = user_info['name'] if user_info else None
        decision = "ALLOW" if user_name and user_name in roles and resource in roles[user_name] else "DENY"
        print(decision)

        timestamp = datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
        log_entry = {
            'timestamp': timestamp,
            'user': user_name if user_name else 'null',
            'resource': resource,
            'decision': decision
        }
        sys.stdout.write(json.dumps(log_entry) + '\n')

if __name__ == "__main__":
    config = parse_access_xml('access.xml')
    process_input(config['users'], config['roles'])

import sys
import xml.etree.ElementTree as ET
from io import StringIO

def parse_access_xml():
    try:
        with open('access.xml', 'r') as f:
            return ET.parse(f)
    except FileNotFoundError:
        sys.stderr.write('ERROR: configuration\n')
        sys.exit(2)
    except ET.ParseError:
        sys.stderr.write('ERROR: configuration\n')
        sys.exit(2)

def build_access_data(tree):
    root = tree.getroot()
    users = {}
    roles = {}

    for user_elem in root.findall('user'):
        name = user_elem.get('name')
        token = user_elem.get('token')
        role = user_elem.get('role')
        users[token] = {'name': name, 'role': role}

    for role_elem in root.findall('role'):
        role_name = role_elem.get('name')
        resource = role_elem.get('resource')
        roles[role_name] = resource

    return users, roles

def process_input(users, roles):
    access_log = []
    for line in sys.stdin:
        parts = line.strip().split()
        if len(parts) != 2:
            continue
        token, resource = parts
        user_data = users.get(token, None)
        if user_data is None:
            decision = 'DENY'
            access_log.append(f"user=null resource={resource} decision=DENY")
        else:
            user_role = user_data['role']
            if user_role in roles and roles[user_role] == resource:
                decision = 'ALLOW'
                access_log.append(f"user={user_data['name']} resource={resource} decision=ALLOW")
            else:
                decision = 'DENY'
                access_log.append(f"user={user_data['name']} resource={resource} decision=DENY")
        print(decision)

    with open('access.log', 'a') as f:
        f.write('\n'.join(access_log) + '\n')

if __name__ == '__main__':
    tree = parse_access_xml()
    users, roles = build_access_data(tree)
    process_input(users, roles)

import sys
import xml.etree.ElementTree as ET
from collections import defaultdict

def parse_access_xml():
    try:
        tree = ET.parse('access.xml')
        root = tree.getroot()
        users = {}
        for user_elem in root.findall('user'):
            name = user_elem.get('name')
            token = user_elem.get('token')
            resources = user_elem.get('resources', '').split()
            users[token] = {'name': name, 'resources': set(resources)}
        return users
    except (ET.ParseError, FileNotFoundError):
        sys.stderr.write('ERROR: configuration\n')
        sys.exit(2)

def main():
    users = parse_access_xml()
    log_file = open('access.log', 'w')

    for line in sys.stdin:
        token, resource = line.strip().split()
        if token not in users:
            decision = 'DENY'
            user_name = 'null'
        else:
            user_name = users[token]['name']
            if resource in users[token]['resources']:
                decision = 'ALLOW'
            else:
                decision = 'DENY'

        print(decision)
        log_file.write(f'user={user_name} resource={resource} decision={decision}\n')

    log_file.close()

if __name__ == '__main__':
    main()
